        return hash(normalize_segment(segment))

    def divide_text(text, threshold=10):
        if len(text) <= threshold:
            return [text]
        mid = len(text) // 2
        left = divide_text(text[:mid], threshold)
        right = divide_text(text[mid:], threshold)
        return left + right

